// Normaliza a entrada vinda do backend App BiT.
// Roteamento é DETERMINÍSTICO pelo campo 'tipo' — sem LLM classificador.
const body = $input.first().json.body || $input.first().json;
const tipo = (body.tipo || '').toString().toLowerCase();
const idioma = (body.idioma === 'es') ? 'es' : 'pt';
const conectividade = (body.conectividade || '').toString().toLowerCase();

return [{ json: {
  tipo: tipo === 'mental-health' ? 'mental-health' : 'orientacao',
  idioma,
  conectividade,
  // Campos de carreira (AssessmentDto.Request)
  nome: body.nome || '',
  idade: body.idade ?? null,
  escolaridade: body.escolaridade || '',
  experiencia: body.experiencia || '',
  hardSkills: body.hardSkills || [],
  softSkills: body.softSkills || [],
  tecnologias: body.tecnologias || [],
  area: body.area || '',
  // Campos de saúde mental
  userId: body.userId ?? body.usuarioId ?? null,
  humor: body.humor || '',
  contexto: body.contexto || body.message || ''
}}];

// Prompt do agente de ACOLHIMENTO (saúde mental).
// Regras invioláveis do App BiT: o agente só gera TEXTO de acolhimento.
// Ele NUNCA decide/menciona derivação ao CVV e NUNCA cita nota numérica.
const d = $('Normalizar Entrada').first().json;
const lang = d.idioma === 'es' ? 'espanhol (neutro latino-americano, tuteo: te/ti/tu)' : 'português do Brasil';
const offline = d.conectividade === 'fraca'
  ? '\n- A conexão do usuário está fraca: priorize ações OFFLINE (caminhada, respiração, escrita, leitura em papel).'
  : '';

const prompt = `Você é o Bit, agente de acolhimento emocional do App BiT.\n` +
`Estado emocional declarado pelo usuário: ${d.humor || 'não informado'}.\n` +
`O que a pessoa escreveu (opcional): "${d.contexto || ''}"\n\n` +
`Sua tarefa: escrever uma resposta de acolhimento breve e humana, no espírito de escutar sem julgar.\n\n` +
`REGRAS OBRIGATÓRIAS:\n` +
`- Responda SOMENTE com JSON válido, sem markdown, sem cercas de código.\n` +
`- Shape exato: {"mensagem": string, "acaoSugerida": string}\n` +
`- mensagem: 2 a 4 frases, empática, específica ao que a pessoa disse. NUNCA cite notas ou números de avaliação.\n` +
`- acaoSugerida: UMA ação concreta e imediata (ex.: um capítulo de livro, um episódio de podcast, caminhar, respiração 4-4-6).\n` +
`- NUNCA mencione encaminhamentos, CVV, telefones de apoio ou decisões de crise — isso é responsabilidade de outro sistema.\n` +
`- Não faça diagnósticos nem use rótulos clínicos.\n` +
`- Fale de como a pessoa está HOJE, a partir do estado declarado e do texto deste check-in. NÃO afirme nem descreva como foi a semana dela: você não vê o histórico.\n` +
`- Escreva em ${lang}.${offline}`;

return [{ json: { prompt } }];

// Prompt do agente de CARREIRA (assessment) com consulta direta ao catálogo real + roadmap da área.
const d = $('Normalizar Entrada').first().json;
const lang = d.idioma === 'es' ? 'espanhol (neutro latino-americano, tuteo)' : 'português do Brasil';

// Catálogo vivo vindo de GET /api/cursos (StandardApiResponse{success,data})
let catalogo = [];
try {
  const resp = $('Buscar Catálogo').first().json;
  const data = resp.data || resp;
  catalogo = (Array.isArray(data) ? data : []).map(c => `- ${c.titulo || c.nome} (${c.instituicao || ''} | área: ${c.area || ''} | ${c.gratuito ? 'gratuito' : 'pago'})`);
} catch (e) { catalogo = []; }
const catalogoTxt = catalogo.length ? catalogo.slice(0, 25).join('\n') : '(catálogo indisponível — recomende trilhas gratuitas conhecidas: Oracle ONE, DIO, Santander Open Academy)';

// Roadmap vivo vindo de GET /api/roadmaps/{area} (StandardApiResponse{success,data}).
// Leitura DEFENSIVA: erro HTTP, success:false, data ausente, área sem roadmap (422) ou
// qualquer exceção de parsing caem no MESMO fallback textual — nunca quebram o prompt.
let roadmapTxt = '(roadmap indisponível para esta área — baseie o plano de desenvolvimento apenas no perfil e no catálogo acima)';
try {
  const rr = $('Buscar Roadmap').first().json;
  const rdata = rr && rr.success !== false ? (rr.data || null) : null;
  if (rdata) {
    const fundamentos = (rdata.habilidades?.fundamentos?.itens || []).map(i => i.nome).filter(Boolean);
    const frameworks = (rdata.habilidades?.frameworks?.itens || []).map(i => i.nome).filter(Boolean);
    const complementares = (rdata.habilidades?.complementares?.itens || []).map(i => i.nome).filter(Boolean);
    const linhas = [];
    if (rdata.titulo) linhas.push(`Trilha de referência: ${rdata.titulo}`);
    if (fundamentos.length) linhas.push(`Fundamentos esperados: ${fundamentos.join(', ')}`);
    if (frameworks.length) linhas.push(`Frameworks/ferramentas esperados: ${frameworks.join(', ')}`);
    if (complementares.length) linhas.push(`Complementares desejáveis: ${complementares.join(', ')}`);
    if (linhas.length) roadmapTxt = linhas.join('\n');
  }
} catch (e) { /* mantém fallback textual */ }

const prompt = `Você é o agente de Avaliação Profissional do App BiT.\n\n` +
`PERFIL DO USUÁRIO:\n` +
`Nome: ${d.nome} | Idade: ${d.idade ?? 'n/i'} | Escolaridade: ${d.escolaridade}\n` +
`Experiência: ${d.experiencia}\n` +
`Hard skills: ${(d.hardSkills||[]).join(', ') || 'nenhuma informada'}\n` +
`Soft skills: ${(d.softSkills||[]).join(', ') || 'nenhuma informada'}\n` +
`Tecnologias: ${(d.tecnologias||[]).join(', ') || 'nenhuma informada'}\n\n` +
`ROADMAP DE REFERÊNCIA PARA A ÁREA DE INTERESSE (${d.area || 'não informada'}):\n${roadmapTxt}\n\n` +
`CATÁLOGO DE CURSOS DISPONÍVEIS NO APP (use APENAS estes ao recomendar cursos):\n${catalogoTxt}\n\n` +
`REGRAS OBRIGATÓRIAS:\n` +
`- Responda SOMENTE com JSON válido, sem markdown, sem cercas de código.\n` +
`- Shape exato: {"compatibilidade": inteiro 0-100, "nivel": string, "pontosFortes": [strings], "gaps": [strings], "planoDesenvolvimento": [strings]}\n` +
  `- As CHAVES do JSON sao identificadores tecnicos FIXOS: compatibilidade, nivel, pontosFortes, gaps, planoDesenvolvimento — NUNCA as traduza; traduza APENAS os valores/textos.\n` +
`- gaps: 2 a 4 lacunas específicas derivadas do perfil real.\n` +
`- planoDesenvolvimento: 2 a 4 passos concretos; cite pelo NOME cursos do catálogo acima quando fizerem sentido para os gaps.\n` +
`- nivel: um de "Júnior Trainee", "Júnior", "Júnior Pleno".\n` +
`- Nunca invente cursos fora do catálogo. Nunca cite notas ou avaliações numéricas do usuário.\n` +
`- Todos os textos em ${lang}.`;

return [{ json: { prompt } }];

// Extrai o texto do Gemini, remove cercas markdown e parseia o JSON.
// Nunca inventa derivarCvv/decisões — devolve exatamente o que o agente gerou.
const r = $input.first().json;
let texto = '';
try {
  texto = r.candidates?.[0]?.content?.parts?.[0]?.text || '';
} catch (e) { texto = ''; }

const limpo = texto.replace(/```json/gi, '').replace(/```/g, '').trim();

try {
  const obj = JSON.parse(limpo);
  if (obj.compatibilidad !== undefined && obj.compatibilidade === undefined) { obj.compatibilidade = obj.compatibilidad; delete obj.compatibilidad; }
  return [{ json: obj }];
} catch (e) {
  // Parse falhou: devolve raw para o backend cair no fallback com diagnóstico.
  return [{ json: { error: 'PARSE_FALHOU', raw: limpo.slice(0, 500) } }];
}
